-- 00_PRECHECK (read only, whole-file F5). P1 = 2 VALID objects. P2 = no row for the two procedures before applying. P3 = 6 rows, each ANCHOR_LINES 1.
SELECT 'P1' AS CHK, OBJECT_NAME, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME, 'YYYY-MM-DD HH24:MI:SS') AS LAST_DDL
  FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW','PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE') AND OBJECT_TYPE IN ('PROCEDURE', 'PACKAGE BODY') ORDER BY 2, 3;
SELECT 'P2' AS CHK, NAME, TYPE, COUNT(*) AS MARKER_LINES FROM USER_SOURCE WHERE TEXT LIKE '%E20261102-RTFLATESTPRICE%' GROUP BY NAME, TYPE ORDER BY 2;
SELECT 'P3' AS CHK, NAME, COUNT(*) AS ANCHOR_LINES, SUBSTR(MIN(TEXT), 1, 60) AS SAMPLE
  FROM USER_SOURCE WHERE TYPE = 'PROCEDURE' AND NAME IN ('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW', 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE')
   AND (TEXT LIKE '%'' : A007--''%' OR TEXT LIKE '%'' : A006--''%' OR TEXT LIKE '%'' : A003--''%') GROUP BY NAME, SUBSTR(TEXT, INSTR(TEXT, ' : A0'), 8) ORDER BY 2, 4;
